mapper.update:
UPDATE daily_log
SET status = 'FAIL',
change_at = NOW()
WHERE status = #{status}
AND todo_ymd < #{todoYmd}

UPDATE daily_log
SET status = 'CANCEL',
    change_at = NOW()
WHERE cycle_seq_no IN (
    SELECT seq_no FROM routine_cycle WHERE routine_seq_no = #{routineSeqNo}
)
AND member_seq_no = #{memberSeqNo}
AND status = 'TODO'

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM daily_log
    WHERE cycle_seq_no = #{cycleSeqNo}
    AND todo_ymd = #{todoYmd}
)
